//! 🔤️ Writes explicit run languages, contents and ordered typed marks under cumulative control.
use super::{SemioTextSnapshot,SemioTextRun,SemioTextMark};
use crate::standards::v1::subsets::base::schema::snapshot::native_encoding::{self,Writer};
use store::sqlite_snapshot::{SnapshotEncoding,SqliteSnapshotControl};
pub(super) fn encode(snapshot:&SemioTextSnapshot,encoding:SnapshotEncoding,control:&mut SqliteSnapshotControl<'_>)->Result<store::os_io::IoPayload,String>{native_encoding::encode(encoding,"semio s.stdio.semio.text.dsl v1\n","s.stdio.semio.text.pack v1",control,|writer,encoding|fields(snapshot,writer,encoding))}
fn mark(value:&SemioTextMark,writer:&mut Writer<'_,'_,'_>,encoding:SnapshotEncoding)->Result<(),String>{writer.delimiter(b"[",encoding)?;writer.byte(if encoding==SnapshotEncoding::Binary{super::mark_kind_tag(value.kind)}else{super::enc_mark_kind(value.kind) as u8})?;writer.delimiter(b",",encoding)?;writer.string(&value.href,encoding)?;writer.delimiter(b"]",encoding)}
fn run(value:&SemioTextRun,writer:&mut Writer<'_,'_,'_>,encoding:SnapshotEncoding)->Result<(),String>{writer.delimiter(b"[",encoding)?;writer.string(&value.language,encoding)?;writer.delimiter(b",",encoding)?;writer.string(&value.content,encoding)?;writer.delimiter(b",",encoding)?;writer.list(&value.marks,encoding,|writer,value|mark(value,writer,encoding))?;writer.delimiter(b"]",encoding)}
pub(crate) fn fields(snapshot:&SemioTextSnapshot,writer:&mut Writer<'_,'_,'_>,encoding:SnapshotEncoding)->Result<(),String>{writer.entities(1)?;if encoding==SnapshotEncoding::Binary{writer.byte(1)?;}else{writer.bytes(b"schema=")?;}writer.string(&snapshot.schema,encoding)?;writer.delimiter(b"\nruns=",encoding)?;writer.list(&snapshot.runs,encoding,|writer,value|run(value,writer,encoding))}
